import sys, re
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from forma_a import P, armar  # noqa: E402
C=Path(__file__).resolve().parents[4]/'contenido'/'04-medio/examenes'
PTS={4:3,6:5,12:3,13:5,18:3,19:5,23:3,24:3,25:5}
Q=[]
def q(sec,en,ops,l,ex,oa):
    n=len(Q)+1
    if n not in PTS: cab="**Pregunta {n}.** *(Selección múltiple)* "
    else: cab=f"**Pregunta {{n}}.** *({'Varias correctas' if len(l)>1 else 'Alternativas'} — {PTS[n]} pts)* "
    Q.append(P(sec,cab,en,ops,l,ex,oa))
def bloque(t,est): return f"## BLOQUE {t}\n\n**Situación de estímulo:** {est}\n\n"
q(bloque("I — OA N°1: El quehacer filosófico (Preguntas 1 a 6)","En un foro escolar se discute si Filosofía debería pasar a ser una asignatura optativa. Una apoderada dice: \"la filosofía no da respuestas definitivas, así que no enseña nada\". Un profesor de Biología responde que la ciencia también avanza a partir de preguntas abiertas, y que muchas de sus preguntas nacieron en la filosofía."),
 "Según la perspectiva socrática sobre la finalidad del quehacer filosófico, ¿para qué sirve filosofar?",
 ["Para memorizar las opiniones de los grandes pensadores de la historia","*Para examinar críticamente nuestras creencias y nuestra forma de vivir","Para encontrar respuestas definitivas que nunca vuelvan a discutirse","Para reemplazar a las ciencias en la explicación de la naturaleza"],"b","Para Sócrates, «una vida sin examen no merece ser vivida»: filosofar es examinar críticamente las propias creencias y la forma de vivir.","OA1")
q("","La apoderada sostiene que la filosofía «no enseña nada» porque no da respuestas definitivas. ¿Qué evaluación es más adecuada?",
 ["Tiene razón, porque solo vale la pena estudiar aquello que tiene una respuesta única, definitiva y comprobable","Tiene razón, porque la filosofía nunca ha influido en la ciencia, en el derecho ni en la política de ningún país","*Confunde el valor de una disciplina con dar respuestas definitivas: la filosofía aporta claridad conceptual y buenos argumentos","No tiene sentido evaluarla, porque toda opinión sobre la filosofía es igual de válida y no se puede discutir con razones"],"c","Que una pregunta no tenga respuesta definitiva no la vuelve inútil: la filosofía aclara conceptos, examina supuestos y desarrolla argumentos, aunque las preguntas sigan abiertas.","OA1")
q("","¿Qué relación entre filosofía y ciencia apoya lo dicho por el profesor de Biología?",
 ["*Muchas ciencias nacieron de la filosofía natural, y la filosofía de la ciencia examina hoy sus fundamentos","La filosofía y la ciencia nunca han tenido ninguna relación a lo largo de la historia de Occidente","La ciencia moderna demostró con experimentos que todas las preguntas filosóficas carecen de sentido","La filosofía solo se ocupa de la religión y la ciencia solo de los números y de los laboratorios"],"a","La física, la biología y otras ciencias surgieron de la filosofía natural, y hoy la filosofía de la ciencia examina sus métodos y supuestos: ambas comparten el origen en preguntas abiertas.","OA1")
q("","Sobre el debate del foro (si Filosofía debe ser optativa), ¿qué opción presenta un argumento a favor y otro en contra, ambos fundamentados?",
 ["A favor: la filosofía es aburrida y difícil para muchos. En contra: a mí personalmente me gusta mucho la filosofía","A favor: todas las asignaturas del liceo deberían ser optativas. En contra: ninguna asignatura del liceo debería serlo nunca","A favor: la apoderada tiene razón porque habló primero en el foro. En contra: el profesor tiene razón porque sabe más que ella","*A favor: hacerla optativa da más tiempo a lo que cada estudiante elige. En contra: todos necesitan herramientas para deliberar sobre lo justo y lo verdadero"],"d","El argumento a favor apela a la libertad de elección de los estudiantes; el argumento en contra, a una necesidad común de herramientas de deliberación. Ambos dan razones y ninguno se presenta como la única postura correcta.","OA1")
q("","Un curso debe decidir si permite usar inteligencia artificial para escribir sus trabajos. ¿Cuál de las siguientes preguntas es propiamente **filosófica**?",
 ["¿Cuánto cuesta una suscripción mensual a una aplicación de inteligencia artificial?","*¿Qué significa que un trabajo sea auténticamente propio?","¿Cuántos estudiantes del curso usan inteligencia artificial cada semana?","¿Qué empresa creó la aplicación de inteligencia artificial más usada?"],"b","Preguntar qué significa que un trabajo sea auténticamente propio exige analizar conceptos (autoría, autenticidad, mérito); las demás se responden con datos.","OA1")
q("","La apoderada agrega: \"Si la filosofía sirviera para algo, ya habría resuelto si existe Dios\". ¿Qué afirmaciones evalúan correctamente este argumento? Marca **todas** las correctas.",
 ["La apoderada demuestra con este ejemplo que la filosofía es inútil","Supone que solo es valioso lo que resuelve una pregunta de manera definitiva","Muchas preguntas científicas también siguen abiertas, y no por eso la ciencia es inútil","Examinar una pregunta abierta puede aclarar las posiciones y las razones de cada una"],"bcd","El argumento supone que solo vale lo que se resuelve definitivamente (b), criterio que tampoco cumple la ciencia (c); además, examinar preguntas abiertas aclara posiciones y razones (d). La primera opción repite la conclusión sin fundamentarla.","OA1")
q(bloque("II — OA N°2: Ética — justicia, libertad e igualdad (Preguntas 7 a 13)","Un municipio debe repartir 100 bicicletas eléctricas gratuitas. Una propuesta es sortearlas entre todos los vecinos inscritos; otra, entregarlas a quienes viven más lejos de su trabajo y no tienen transporte público cercano; una tercera, dárselas a los primeros 100 que se inscriban por internet. El alcalde dice: \"elijamos el criterio que reduzca más el uso del auto en la comuna\"."),
 "¿Qué distingue a una norma moral de una norma legal?",
 ["Que la norma moral siempre está escrita en el Código Penal y la aplican los tribunales de justicia","Que la norma legal depende solo de la conciencia de cada persona y no la dicta ninguna autoridad, mientras la moral la fija el Congreso","Que ambas son exactamente iguales, las dicta el mismo órgano del Estado y su incumplimiento tiene siempre las mismas sanciones penales","*Que la moral se funda en valores y en la conciencia, mientras la ley la dicta el Estado y su incumplimiento tiene sanción jurídica"],"d","La norma moral se funda en valores que la persona reconoce en su conciencia; la norma legal la establece el Estado y su incumplimiento tiene una sanción jurídica.","OA2")
q("","La propuesta de **sortear** las bicicletas entre todos los vecinos inscritos se fundamenta principalmente en:",
 ["*La igualdad de trato: todos tienen la misma probabilidad de recibir una","La necesidad: se entrega primero a quienes más la requieren","El mérito: se entrega a quienes más se esfuerzan en su trabajo","La eficiencia: se entrega a quien la vaya a usar más horas"],"a","El sorteo da a cada vecino inscrito la misma probabilidad: es un criterio de igualdad de trato, sin considerar diferencias de necesidad o mérito.","OA2")
q("","La propuesta de entregar las bicicletas a quienes viven más lejos de su trabajo y no tienen transporte cercano se fundamenta principalmente en:",
 ["El mérito académico o laboral de cada uno de los postulantes","La igualdad estricta entre todos los vecinos inscritos en el municipio","*La equidad: atender primero a quienes tienen mayor necesidad","El orden de llegada de las inscripciones a la página web del municipio"],"c","Priorizar a quienes más lo necesitan (viven lejos y sin transporte) es un criterio de equidad: se trata distinto a quienes están en situaciones distintas.","OA2")
q("","¿Qué problema ético puede tener el criterio de entregar las bicicletas a «los primeros 100 que se inscriban por internet»?",
 ["Que favorece siempre a las personas que más las necesitan para llegar a su trabajo","*Que parece neutral, pero favorece a quienes tienen más tiempo, conexión e información","Que obliga al municipio a sortear las bicicletas entre todos los vecinos de la comuna","Que impide que cualquier vecino de la comuna pueda recibir una bicicleta eléctrica"],"b","El orden de llegada parece imparcial, pero favorece a quienes tienen internet, tiempo e información: puede reproducir desigualdades que ya existen.","OA2")
q("","El alcalde propone elegir «el criterio que reduzca más el uso del auto en la comuna». ¿Qué tipo de razonamiento ético usa?",
 ["*Consecuencialista: evalúa el criterio según sus resultados para la comunidad","Deontológico: evalúa el criterio según deberes que valen sin importar los resultados","De la virtud: evalúa el criterio según el carácter de quien recibe la bicicleta","Relativista: considera que cualquier criterio vale lo mismo para todos"],"a","El alcalde juzga los criterios por sus consecuencias (menos uso del auto): es un razonamiento consecuencialista, como el utilitarismo.","OA2")
q("","Un vecino reclama: «Es injusto que yo, que pago más impuestos, no reciba una bicicleta». ¿Qué concepto de justicia invoca y qué se le puede responder?",
 ["Invoca la justicia distributiva según la necesidad; se le puede responder que él es, sin duda, quien más la necesita en toda la comuna","Invoca la igualdad estricta entre los vecinos; se le puede responder que el sorteo siempre lo favorece a él por sobre los demás","*Invoca una justicia según lo que cada uno aporta; se le puede responder que los bienes públicos suelen repartirse según criterios de necesidad o igualdad","No invoca ningún concepto de justicia, porque los impuestos que paga una persona no tienen ninguna relación con lo justo"],"c","El vecino pide recibir en proporción a lo que aporta; frente a eso se puede responder que los bienes públicos suelen distribuirse según necesidad o igualdad, no según lo que cada uno paga.","OA2")
q("","Sobre el reparto de las bicicletas, ¿qué afirmaciones aplican correctamente distintos marcos éticos? Marca **todas** las correctas.",
 ["Un utilitarista elegiría el criterio que produzca mayores beneficios para la comunidad","Solo existe un criterio legítimo, y quienes piensan distinto son irracionales","Un enfoque inspirado en Rawls priorizaría a los menos aventajados, como quienes no tienen transporte","Distintos marcos éticos pueden llegar a conclusiones diferentes sobre el mismo reparto"],"acd","El utilitarismo busca los mayores beneficios (a), el enfoque de Rawls favorece a los menos aventajados (c) y por eso distintos marcos pueden concluir distinto (d). Afirmar que solo un criterio es legítimo es una postura dogmática.","OA2")
q(bloque("III — OA N°4: Evaluar argumentos filosóficos (Preguntas 14 a 19)","En una columna de opinión, una autora escribe: \"Las tareas para la casa deben eliminarse por completo. Mi hermano chico llora cada vez que tiene tareas, así que es evidente que dañan a todos los niños. O eliminamos las tareas, o aceptamos que la infancia se arruine. Además, Finlandia tiene muy buenos resultados educativos y casi no da tareas\"."),
 "En este texto, ¿cuál es la tesis que la autora defiende?",
 ["Que su hermano chico debería cambiarse de colegio","Que Finlandia tiene el mejor sistema educativo del mundo","*Que las tareas para la casa deben eliminarse por completo","Que los niños deberían estudiar más horas en la casa"],"c","La tesis es la afirmación que el texto busca sostener: «Las tareas para la casa deben eliminarse por completo»; lo demás son razones a su favor.","OA4")
q("","La frase «mi hermano chico llora cada vez que tiene tareas, así que es evidente que dañan a todos los niños» corresponde a:",
 ["Un argumento deductivo válido","Una apelación a la autoridad","Una falsa dicotomía","*Una generalización apresurada"],"d","A partir de un solo caso (su hermano) concluye algo sobre todos los niños: es una generalización apresurada.","OA4")
q("","La frase «o eliminamos las tareas, o aceptamos que la infancia se arruine» corresponde a:",
 ["*Una falsa dicotomía, porque ignora opciones intermedias","Una generalización apresurada, porque parte de un caso","Un argumento inductivo fuerte, porque usa muchos datos","Una apelación a las emociones, porque cita un estudio"],"a","Presenta solo dos opciones extremas, cuando existen alternativas intermedias (menos tareas, tareas breves o voluntarias): es una falsa dicotomía.","OA4")
q("","¿Qué evaluación es más adecuada del ejemplo de Finlandia que usa la autora?",
 ["Prueba con total certeza que eliminar las tareas mejora los resultados educativos en cualquier país del mundo","*Es un dato de otro contexto: no prueba que la falta de tareas cause los resultados, porque influyen muchos otros factores","Es una falacia ad hominem, porque ataca personalmente a los profesores que dan tareas en los colegios de Chile","Es irrelevante, porque los datos educativos de otros países nunca sirven para nada en ninguna discusión"],"b","Que Finlandia tenga buenos resultados y pocas tareas no prueba que lo segundo cause lo primero: hay muchos otros factores (formación docente, condiciones sociales). Es una correlación, no una causa demostrada.","OA4")
q("","La autora concluye que las tareas deben eliminarse **por completo**. ¿Qué supuesto implícito tiene esta conclusión y por qué conviene hacerlo explícito?",
 ["*Que ningún tipo de tarea puede ser beneficioso; hacerlo explícito permite discutir alternativas, como tareas breves o voluntarias","Que las tareas son siempre beneficiosas; hacerlo explícito permite aumentar su cantidad en todos los cursos","Que los niños no deberían ir al colegio; hacerlo explícito permite cerrar las escuelas por la tarde","Que Finlandia es un país muy frío; hacerlo explícito permite comparar el clima de ambos países"],"a","Pedir eliminar todas las tareas supone, sin decirlo, que ninguna forma de tarea sirve; al hacerlo explícito se puede evaluar si es razonable o si hay opciones intermedias.","OA4")
q("","Sobre el texto completo de la autora, ¿qué afirmaciones son correctas? Marca **todas** las correctas.",
 ["Aunque el argumento tenga falacias, la tesis podría ser verdadera por otras razones","La falsa dicotomía ignora posturas intermedias que podrían ser razonables","El caso de su hermano es una experiencia personal, insuficiente como evidencia general","Como el argumento tiene falacias, queda demostrado que las tareas son buenas"],"abc","Evaluar un argumento no equivale a decidir la verdad de la tesis: un mal argumento no prueba lo contrario (por eso la última opción es incorrecta). La falsa dicotomía y la generalización desde un solo caso son debilidades del texto.","OA4")
q(bloque("IV — OA N°5: El impacto de las ideas filosóficas en el mundo actual (Preguntas 20 a 25)","Un consultorio usa un algoritmo para decidir el orden de atención de los pacientes, según datos de sus consultas anteriores. El sistema fue entrenado con datos de un hospital de Santiago y se aplica en una comuna rural. Al mismo tiempo, una red social ordena las noticias de cada usuario según lo que más tiempo lo mantiene conectado."),
 "El algoritmo del consultorio da prioridad a quienes han consultado más veces en el pasado. ¿Qué problema ético puede generar?",
 ["Que atiende a todos los pacientes exactamente en el mismo orden de llegada al consultorio, sin excepciones","Que obliga a los médicos a revisar cada caso sin ninguna ayuda tecnológica ni registro de datos","*Que puede postergar a quienes antes tuvieron menos acceso a la salud, reproduciendo desigualdades","Que impide que los pacientes de la comuna reciban atención médica durante el fin de semana"],"c","Si prioriza a quienes más consultaron, puede postergar a quienes antes tuvieron menos acceso (por distancia o recursos): reproduciría desigualdades previas, un problema de justicia.","OA5")
q("","Los usuarios que creen todo lo que la red social les muestra, sin preguntarse por qué ven esas noticias, adoptan una actitud:",
 ["Crítica, porque revisan cada fuente antes de opinar","Escéptica radical, porque dudan de toda la información","Científica, porque ponen a prueba lo que leen","*Dogmática, porque aceptan la información sin examinarla"],"d","Aceptar lo que el algoritmo muestra sin examinarlo ni preguntarse por qué aparece es una actitud dogmática, contraria al pensamiento crítico.","OA5")
q("","Que la red social ordene las noticias según lo que más tiempo mantiene conectado a cada usuario plantea principalmente un problema de:",
 ["*Autonomía: el sistema puede orientar la atención y las opiniones sin que la persona lo note","Propiedad: los usuarios pierden el derecho a comprar su propio teléfono celular","Igualdad: todos los usuarios reciben exactamente las mismas noticias, en el mismo orden","Salud física: las noticias producen enfermedades contagiosas en quienes las leen"],"a","Si el orden busca captar la atención y no informar, el sistema puede orientar lo que la persona ve y piensa sin que lo note: es un problema para su autonomía.","OA5")
q("","El algoritmo del consultorio fue entrenado con datos de un hospital de Santiago y se usa en una comuna rural. ¿Qué problema de razonamiento hay en aplicarlo sin revisarlo?",
 ["Ninguno, porque los datos de salud de las personas son exactamente iguales en todas las comunas del país","*Generaliza desde una muestra que no representa a la población rural, por lo que sus conclusiones pueden ser erróneas allí","Es una falacia ad hominem, porque ataca personalmente a los médicos que trabajan en la comuna rural","Es un argumento deductivo válido, porque usa datos reales de pacientes de un hospital de Santiago"],"b","Los datos de un hospital urbano pueden no representar a la población rural (otras distancias, enfermedades y acceso): aplicar el sistema sin revisarlo es generalizar desde una muestra no representativa.","OA5")
q("","¿Qué conexiones entre estos usos de algoritmos y las ideas filosóficas son pertinentes? Marca **todas** las correctas.",
 ["Los algoritmos son neutrales por definición, así que no plantean preguntas filosóficas","El orden de atención en el consultorio plantea preguntas de justicia","Ordenar noticias para captar la atención plantea preguntas sobre la libertad y la autonomía","Usar datos personales de salud plantea preguntas sobre la privacidad y la dignidad"],"bcd","El orden de atención plantea preguntas de justicia, el orden de las noticias sobre la autonomía y el uso de datos de salud sobre la privacidad; los algoritmos no son neutrales por definición, porque los diseñan personas con criterios y datos.","OA5")
q("","Una autoridad de salud afirma: «El algoritmo es matemático, así que no puede ser injusto». ¿Qué afirmaciones evalúan correctamente esta idea? Marca **todas** las correctas.",
 ["Confunde la precisión de un cálculo con la justicia de sus criterios","Los datos y los criterios del algoritmo los eligen personas, que pueden equivocarse o tener sesgos","Debe haber responsables humanos y la posibilidad de revisar y corregir sus decisiones","Tiene razón: todo lo que es matemático es siempre justo e imparcial"],"abc","Un cálculo puede ser preciso y aun así aplicar criterios injustos (a), porque los datos y criterios los eligen personas (b); por eso deben existir responsables y revisión (c). Lo matemático no es justo por sí mismo.","OA5")
armar(C/'filosofia-examen-forma-b.md', C/'filosofia-examen-forma-a.md', Q,
  fila=lambda i,p,cl: f"| {i} | {p.letra}. {p.explicacion} | {p.oa} | {PTS.get(i,1)} |",
  reemplazos={"— Forma B":"— Forma A","— FORMA B":"— FORMA A","Forma B: preguntas propias":"Forma A: preguntas propias, distintas de la Forma B","última actualización: 2026-08-11":"última actualización: 2026-11-17"},
  inicio_preguntas="## BLOQUE I")
ruta=C/'filosofia-examen-forma-a.md'; s=ruta.read_text(encoding="utf-8")
s="\n".join(l for l in s.split("\n") if not (re.match(r"^\| (\d+) \| ", l) and int(re.match(r"^\| (\d+) \| ", l).group(1)) in PTS and "| OA" in l))
for i,p in enumerate(Q,1):
    if i in PTS:
        clave = p.clave_texto() if len(p.letra)>1 else f"{p.letra}) {p.ordenadas()['abcd'.index(p.letra)]}"
        nuevo=f"**Pregunta {i} ({p.oa}, {PTS[i]} pts).** {clave}. {p.explicacion}"
        s,k=re.subn(rf"^\*\*Pregunta {i} \(OA[0-9/OA]+, \d pts[^)]*\)\.\*\*.*$", lambda m: nuevo, s, count=1, flags=re.M)
        assert k==1, i
ruta.write_text(s, encoding="utf-8")
if __name__=="__main__":
    from collections import Counter; print(Counter(p.letra for p in Q), len(Q))
